//! Engine sanity: reproduce a Go-generated parity vector through the `lighters`
//! crate as used by ACS. This proves the engine wiring before we build the ABI.
//!
//! Vector origin: `lighters`' own `tests/vectors.json`, generated by
//! `lighter-go/cmd/vectors`. Byte-for-byte hash + JSON equality.

use lighters::transactions::{CreateOrder, OrderInfo, TxInfo};

const CHAIN_ID: u32 = 304;
const EXPIRED_AT: i64 = 1_700_000_000_000;
const NONCE: i64 = 42;

#[test]
fn create_order_matches_go_vector() {
    let mut tx = CreateOrder {
        account_index: 1,
        api_key_index: 0,
        order: OrderInfo {
            market_index: 0,
            client_order_index: 1,
            base_amount: 1000,
            price: 50000,
            is_ask: 0,
            order_type: 0,
            time_in_force: 1,
            reduce_only: 0,
            trigger_price: 0,
            order_expiry: 99_999_999,
        },
        expired_at: EXPIRED_AT,
        nonce: NONCE,
        sig: Vec::new(),
        signed_hash: String::new(),
        attributes: None,
    };

    tx.validate().expect("validate");
    let hash = tx.hash(CHAIN_ID).expect("hash");
    assert_eq!(
        hex::encode(hash),
        "df8102da5ffa45e0b14a4fffdcab19d21d52039ba9036396f3a3c11c21145baaebece4f51e983629",
        "create_order message hash must match Go"
    );

    // Dummy sig 0..80, matching the parity test's fixed input.
    tx.set_signature((0u16..80).map(|i| i as u8).collect(), String::new());
    assert_eq!(
        tx.to_json().expect("json"),
        r#"{"AccountIndex":1,"ApiKeyIndex":0,"MarketIndex":0,"ClientOrderIndex":1,"BaseAmount":1000,"Price":50000,"IsAsk":0,"Type":0,"TimeInForce":1,"ReduceOnly":0,"TriggerPrice":0,"OrderExpiry":99999999,"ExpiredAt":1700000000000,"Nonce":42,"Sig":"AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8gISIjJCUmJygpKissLS4vMDEyMzQ1Njc4OTo7PD0+P0BBQkNERUZHSElKS0xNTk8=","L2TxAttributes":null}"#,
        "create_order JSON must match Go"
    );
}
